// Источник — по адресу сайта; свежие — за последние сутки, не больше пяти с сайта.
const names = { 'habr.com': 'Хабр', '3dnews.ru': '3DNews', 'www.ixbt.com': 'iXBT' }
const dayAgo = Date.now() - 24 * 60 * 60 * 1000
const perSource = {}
const result = []
for (const item of $input.all()) {
  const news = item.json
  const link = news.link.split('?')[0]
  const site = link.split('/')[2]
  const source = names[site] ?? site
  const time = new Date(news.isoDate ?? news.pubDate).getTime()
  perSource[source] = (perSource[source] ?? 0)
  if (time < dayAgo || perSource[source] >= 5) continue
  perSource[source]++
  result.push({ json: {
    id: link,
    date: new Date(time).toISOString(),
    source,
    title: news.title,
    text: (news.contentSnippet ?? '').replace(/\s+/g, ' ').slice(0, 1500),
    link,
  } })
}
return result

